def price(self, items: Sequence[LineItem]) -> Money:
    """Return the base price, less the discount if the quantity qualifies."""
    base = self._base.price(items)
    total_qty = sum(item.quantity for item in items)
    if total_qty < self.threshold:
        return base
    # discount is floor division of the base amount by the percent off
    discount_amount = (base.amount * self.percent_off) // 100
    return Money(base.amount - discount_amount)
